import{_ as e,c as r,o as n,a3 as o}from"./chunks/framework.Cc9k46oU.js";const y=JSON.parse('{"title":"SyncSeries 製品紹介書および導入提案書（PDFダウンロード）","description":"SyncSeries 統合パンフレット・マスター提案書、および全12製品群（SyncVerse、SyncInsight、SyncLLM、SyncWatch、SyncBoot、SyncCMS、SyncShop、SyncOps、SyncAPIM、SyncETA、SyncCrawl、SyncSDK）の個別紹介書・導入提案書 PDF ダウンロードセンター","frontmatter":{"title":"SyncSeries 製品紹介書および導入提案書（PDFダウンロード）","description":"SyncSeries 統合パンフレット・マスター提案書、および全12製品群（SyncVerse、SyncInsight、SyncLLM、SyncWatch、SyncBoot、SyncCMS、SyncShop、SyncOps、SyncAPIM、SyncETA、SyncCrawl、SyncSDK）の個別紹介書・導入提案書 PDF ダウンロードセンター","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/proposals/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/proposals/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/proposals/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/proposals/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/proposals/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncSeries 製品紹介書および導入提案書（PDFダウンロード） | Empasy Docs"}],["meta",{"property":"og:description","content":"SyncSeries 統合パンフレット・マスター提案書、および全12製品群（SyncVerse、SyncInsight、SyncLLM、SyncWatch、SyncBoot、SyncCMS、SyncShop、SyncOps、SyncAPIM、SyncETA、SyncCrawl、SyncSDK）の個別紹介書・導入提案書 PDF ダウンロードセンター"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/proposals/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncSeries 製品紹介書および導入提案書（PDFダウンロード） | Empasy Docs"}],["meta",{"name":"twitter:description","content":"SyncSeries 統合パンフレット・マスター提案書、および全12製品群（SyncVerse、SyncInsight、SyncLLM、SyncWatch、SyncBoot、SyncCMS、SyncShop、SyncOps、SyncAPIM、SyncETA、SyncCrawl、SyncSDK）の個別紹介書・導入提案書 PDF ダウンロードセンター"}]]},"headers":[],"relativePath":"ja/proposals/index.md","filePath":"ja/proposals/index.md","lastUpdated":1795490386000}'),a={name:"ja/proposals/index.md"};function l(s,t,d,c,g,i){return n(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="製品紹介書および導入提案書-pdfダウンロード" tabindex="-1">製品紹介書および導入提案書（PDFダウンロード） <a class="header-anchor" href="#製品紹介書および導入提案書-pdfダウンロード" aria-label="Permalink to “製品紹介書および導入提案書（PDFダウンロード）”">​</a></h1><p>社内の導入稟議、経営陣への報告、アーキテクチャ技術審査、次世代 SI/AX 事業の提案にそのまま添付でき、プレゼンテーション資料としても活用できる <strong>SyncSeries 公式サマリーパンフレット（8ページ）、全社統合導入提案書（21ページ）、および製品別技術紹介書・導入提案書（12〜15ページ、16:9 ワイドプレゼンテーション規格）</strong> の一覧です。</p><p>すべての資料は、初めて製品に触れる方でも <strong>「この製品が何であり、なぜ必要なのか」</strong> を一目で理解できるよう、直感的な表現と実際の稼働画面キャプチャで構成されています。</p><ul><li><strong>製品別提案書（12p）標準目次</strong>： <ol><li><strong>一目でわかる製品定義＆4大コア機能サマリー</strong>（表紙）</li><li><strong>なぜこの製品が必要なのか？</strong>（現場で直面する4つの課題 vs 解決アプローチ）</li><li><strong>どのような順序で動作するのか？</strong>（4ステップの動作原理および AI 自動実行 vs 人間の承認の役割分担）</li><li><strong>実画面で見るコア機能 1〜4</strong>（<code>いつ使う画面ですか？</code> ＋ <code>この画面でできる4つのこと</code> ＋ 高解像度の実画面）</li><li><strong>3重の安全装置および運用統制</strong>（事前ブロックガードレール・変更前後比較承認・1-Click 以前の状態への復元）</li><li><strong>社内既存システム連携＆他エージェントとの協働構成</strong>（単独導入 vs エージェント連合連携）</li><li><strong>導入前後の業務変化（Before vs After）および定量的期待効果</strong></li><li><strong>4段階の段階的導入ロードマップおよび推奨サーバー・技術仕様</strong></li></ol></li></ul><hr><h2 id="_1-統合サマリーパンフレットおよびマスター導入提案書" tabindex="-1">1. 統合サマリーパンフレットおよびマスター導入提案書 <a class="header-anchor" href="#_1-統合サマリーパンフレットおよびマスター導入提案書" aria-label="Permalink to “1. 統合サマリーパンフレットおよびマスター導入提案書”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">資料名</th><th style="text-align:left;">対象読者および主な収録内容（誰向けですか？）</th><th style="text-align:center;">ページ数</th><th style="text-align:center;">ダウンロード</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncSeries 統合サマリーパンフレット</strong><br>(<code>SyncSeries_Brochure_v1.0.pdf</code>)</td><td style="text-align:left;"><strong>経営陣・業務部門長・3分で全体像を把握したい場合</strong><br>• なぜ従来の業務システムや単なるチャットボットだけでは現場の業務が減らないのか？<br>• 4-Tier 全体構成および12大専門エージェントラインナップの役割マップ<br>• 企業が安心して利用できる3大安全装置（比較承認・リスク遮断・1秒復元）および導入効果</td><td style="text-align:center;">8p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSeries_Brochure_v1.0.pdf" target="_blank" download="SyncSeries_Brochure_v1.0.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncSeries 全社統合導入提案書</strong><br>(<code>SyncSeries_Master_Proposal.pdf</code>)</td><td style="text-align:left;"><strong>CIO・CTO・PMO・デジタルトランスフォーメーション（AX/DX）企画チーム技術審査用</strong><br>• 現場と開発・セキュリティ組織における慢性的なボトルネック診断および2つの実行パス（運用 vs 開発）<br>• 12大エージェント全製品の詳細機能・実画面および3大商用サービス・23件の特許現況<br>• 3大複合エージェント協働シナリオ、Before/After 成果、推奨サーバー仕様およびロードマップ</td><td style="text-align:center;">21p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSeries_Master_Proposal.pdf" target="_blank" download="SyncSeries_Master_Proposal.pdf">PDFダウンロード</a></td></tr></tbody></table><hr><h2 id="_2-統合管制・データ分析・ai-コスト・セキュリティインテリジェンス-tier-1-tier-2" tabindex="-1">2. 統合管制・データ分析・AI コスト・セキュリティインテリジェンス（Tier 1 &amp; Tier 2） <a class="header-anchor" href="#_2-統合管制・データ分析・ai-コスト・セキュリティインテリジェンス-tier-1-tier-2" aria-label="Permalink to “2. 統合管制・データ分析・AI コスト・セキュリティインテリジェンス（Tier 1 &amp; Tier 2）”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">製品名（一行定義）</th><th style="text-align:left;">どのような課題を解決する製品ですか？（主な収録内容）</th><th style="text-align:center;">ページ数</th><th style="text-align:center;">ダウンロード</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncVerse</strong><br>（全社エージェント管制塔＆開発スタジオ）</td><td style="text-align:left;">• <strong>1か所ですべてのエージェントを指揮</strong>：自然言語の指示1行で分析・コンテンツ・コマース・セキュリティエージェントを連鎖実行<br>• <strong>5段階スペックスタジオ</strong>：要件を機能・画面・DB・API 設計書および開発コードへと段階的に完成<br>• <strong>品質監査＆4大成果物</strong>：コード・Web セキュリティ/SEO 統合診断、多者間承認（HITL）、SI 4大成果物を自動生成</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncVerse_Proposal.pdf" target="_blank" download="SyncVerse_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncInsight</strong><br>（セキュア自然言語 DB 分析＆ディープリサーチ）</td><td style="text-align:left;">• <strong>SQL 不要で3秒で DB 照会</strong>：開発者のデータ抽出待ち（2〜3日）なしに、自然言語の質問で表やチャートを即座に確認<br>• <strong>データ毀損リスク 0%</strong>：Apache Calcite 構文木（AST）ガードレールにより更新・削除クエリを根本から遮断<br>• <strong>原因分析から実行連携まで</strong>：社内 DB と文書ナレッジ（pgvector）を結合したディープリサーチおよび後続アクションカードを提案</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncInsight_Proposal.pdf" target="_blank" download="SyncInsight_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncLLM</strong><br>（中央 AI ゲートウェイ＆トークンコスト管理）</td><td style="text-align:left;">• <strong>AI トークンコスト 50% 以上削減</strong>：質問の難易度別の最適モデル自動割り当ておよび類似質問への0円応答（セマンティックキャッシュ）<br>• <strong>AI 障害時に1秒以内で自動迂回</strong>：特定の AI 障害時に待機モデルまたは社内ローカル LLM（vLLM/Ollama）へ無停止切り替え<br>• <strong>予算上限＆個人情報保護</strong>：部門別の予算統制（FinOps）および外部 AI 送信直前の個人情報（PII）リアルタイムマスキング</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncLLM_Proposal.pdf" target="_blank" download="SyncLLM_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncWatch</strong><br>（グローバルセキュリティ脅威＆デュアルルールコンパイラ）</td><td style="text-align:left;">• <strong>8大公認セキュリティチャネルを24時間収集</strong>：KISA（韓国インターネット振興院）・米国 CISA・NVD・GitHub などの新規脆弱性をリアルタイム収集<br>• <strong>テキスト通知を実行ルールへ変換</strong>：開発チーム向けの「脆弱パッケージ・コード点検基準」と運用チーム向けの「API 遮断ルール」を同時生成<br>• <strong>正検知 100%・誤検知 0% の検証済み配信</strong>：独自サンドボックスで攻撃・正常サンプル試験を通過した安全な防御ルールのみを配信</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncWatch_Proposal.pdf" target="_blank" download="SyncWatch_Proposal.pdf">PDFダウンロード</a></td></tr></tbody></table><hr><h2 id="_3-業務ドメイン運用エージェントおよびコーディング開発キット-tier-3-tier-4" tabindex="-1">3. 業務ドメイン運用エージェントおよびコーディング開発キット（Tier 3 &amp; Tier 4） <a class="header-anchor" href="#_3-業務ドメイン運用エージェントおよびコーディング開発キット-tier-3-tier-4" aria-label="Permalink to “3. 業務ドメイン運用エージェントおよびコーディング開発キット（Tier 3 &amp; Tier 4）”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">製品名（一行定義）</th><th style="text-align:left;">どのような課題を解決する製品ですか？（主な収録内容）</th><th style="text-align:center;">ページ数</th><th style="text-align:center;">ダウンロード</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncBoot</strong><br>（エンタープライズ標準バックオフィスフレームワーク）</td><td style="text-align:left;">• <strong>新規システム構築期間 50% 短縮</strong>：組織・ユーザー・ロール権限・決裁・辞書コード・監査ログが完備された標準バックオフィス<br>• <strong>再デプロイ不要の DB 動的メニュー</strong>：フロントエンドのコード修正なしに管理画面からメニューツリーとボタン権限を即座に制御<br>• <strong>無停止リアルタイム環境設定</strong>：AES-256 暗号化保管、ソケット接続事前診断およびマルチサーバーでの1秒以内設定ホットスワップ</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncBoot_Proposal.pdf" target="_blank" download="SyncBoot_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncCMS</strong><br>（AI コンテンツ公開＆検索・AI 引用診断）</td><td style="text-align:left;">• <strong>3段階エージェント協働執筆</strong>：コンテンツギャップ分析によるテーマ推薦からドラフト作成・品質検収・承認公開までを自動化<br>• <strong>SEO・AEO・GEO 100点採点</strong>：検索エンジン露出はもちろん ChatGPT・Perplexity に引用されやすいよう JSON-LD および本文をコーチング<br>• <strong>用語集ベースの多言語ローカライズ</strong>：ブランド固有名詞を保持したまま英語・日本語記事と現地検索タグを同時に完成</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncCMS_Proposal.pdf" target="_blank" download="SyncCMS_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncShop</strong><br>（8モジュール MSA Eコマース＆マージン保護価格管理）</td><td style="text-align:left;">• <strong>8つの独立マイクロサービス（MSA）</strong>：Gateway・Auth・Admin・Portal・Search などが分離され、トラフィック急増時にも障害を隔離<br>• <strong>逆ザヤ（赤字販売）防止の価格調整</strong>：原価に対する最小マージン率基準を自動計算し、基準未満の商品を事前に保護<br>• <strong>1-Click 価格スナップショット復元</strong>：変更前の価格表を自動バックアップし、キャンペーン終了や入力ミス時に1秒で元の価格を復旧</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncShop_Proposal.pdf" target="_blank" download="SyncShop_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncOps</strong><br>（韓国型 SI 損益・稼働率・コンプライアンス）</td><td style="text-align:left;">• <strong>二重単価リアルタイム営業利益率</strong>：発注元との契約単価と実投入要員の原価を月次で照合し、赤字リスクを早期アラート<br>• <strong>月次要員 M/M ヒートマップ＆ KOSA</strong>：全社員のプロジェクト投入率ヒートマップ管理および入札提案書向けの要員プロフィールをワンクリック抽出<br>• <strong>下請法15日アラート＆電子研究ノート</strong>：入金後15日以内の下請代金支払い、4大保証保険の満期、SHA-256 政府課題研究ノート</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncOps_Proposal.pdf" target="_blank" download="SyncOps_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncAPIM</strong><br>（リアルタイム API セキュリティ管制＆自律仮想パッチ）</td><td style="text-align:left;">• <strong>隠れた未登録 API を100%発見</strong>：実流入トラフィックのリバースエンジニアリングにより、ドキュメントにない Shadow API および機密レスポンスフィールドを検出<br>• <strong>再デプロイ不要で1分以内に仮想パッチ</strong>：正常トラフィック200件のバックテスト（誤検知 0.0%）検証後、1ms インラインエンジンへ無停止反映<br>• <strong>文脈認識型の個人情報マスキング＆ eBPF</strong>：注文番号の誤検知なく住民登録番号・カード番号・口座番号のみをマスキングおよび 0.29% 超低負荷カーネル防御</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncAPIM_Proposal.pdf" target="_blank" download="SyncAPIM_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncETA</strong><br>（Web画面テスト自動化・サイト欠陥検出および履歴管理）</td><td style="text-align:left;">• <strong>操作録画・Excel/一行文変換・マルチアカウント</strong>：クリック録画、既存Excel/CSV試験表と代表・標本URLによる多ページ点検、仮想キーパッド・Cookieバナー自動通過<br>• <strong>シナリオ不要のリンク・画面全数診断</strong>：サイト知識グラフで404リンク・遷移不一致・文字重なり・空白領域を自動検出し、曖昧な項目を<code>[確認必要]</code>へ誠実分類<br>• <strong>バグカンバン＆<code>[今すぐ確認]</code>ワンクリック再検証</strong>：写真付きチケット自動起票、重複防止、<code>[バグではありません]</code>永続記憶、Jira・Jenkins・GitHub Actions・Slack連携</td><td style="text-align:center;">15p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncETA_Proposal.pdf" target="_blank" download="SyncETA_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncCrawl</strong><br>（Web データ自己修復収集＆ RAG ナレッジ化）</td><td style="text-align:left;">• <strong>サイト改修に適応するコレクター</strong>：対象 Web ページの構造が変わっても AI がセレクタを自律修正し、中断なくデータを収集<br>• <strong>広告除去クリーン Markdown ＆表保持</strong>：雑多なメニューや広告を取り除き、表構造を保ったクリーンな Markdown と JSON を抽出<br>• <strong>pgvector 即時格納＆ハッシュ証跡</strong>：AI 検索（RAG）用のベクトルチャンクとして即座に格納し、SHA-256 ハッシュチェーンで出典の完全性を証明</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncCrawl_Proposal.pdf" target="_blank" download="SyncCrawl_Proposal.pdf">PDFダウンロード</a></td></tr><tr><td style="text-align:left;"><strong>SyncSDK</strong><br>（15大コーディングエンジンルーター＆エージェントキット）</td><td style="text-align:left;">• <strong>15種のコーディング AI を無停止で自由切り替え</strong>：Claude Code・Antigravity・Copilot・Cursor・OpenHands など15大エンジンをランタイムでホットスワップ<br>• <strong>3階層社内ハーネス＆4段階ビルド修復</strong>：社内のコーディング標準を強制注入し、コンパイル・テストエラーを自律修正して Git PR を作成<br>• <strong>既存システムエージェントスターター＆成果物</strong>：Spring Boot システムを1日で MCP エージェントとして接続し、4大成果物を自動生成</td><td style="text-align:center;">12p</td><td style="text-align:center;"><a href="/downloads/proposals/SyncSDK_Proposal.pdf" target="_blank" download="SyncSDK_Proposal.pdf">PDFダウンロード</a></td></tr></tbody></table><hr><h2 id="_4-導入目的別-おすすめ資料組み合わせガイド" tabindex="-1">4. 導入目的別 おすすめ資料組み合わせガイド <a class="header-anchor" href="#_4-導入目的別-おすすめ資料組み合わせガイド" aria-label="Permalink to “4. 導入目的別 おすすめ資料組み合わせガイド”">​</a></h2><p>自社の現在の課題と導入目的に合わせて以下の組み合わせで資料をダウンロードしてご検討いただくと、意思決定にかかる時間を大幅に短縮できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">自社の現在の課題 / 導入目的</th><th style="text-align:left;">おすすめダウンロード PDF の組み合わせ</th><th style="text-align:left;">主な検討ポイント</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. 経営陣への初期報告および全社 AI 変革（AX）企画</strong></td><td style="text-align:left;"><code>SyncSeries_Brochure_v1.0.pdf</code> (8p)<br>+ <code>SyncSeries_Master_Proposal.pdf</code> (21p)</td><td style="text-align:left;">会話だけのチャットボットと実行型エージェントの違い、4-Tier 12大製品ラインナップ、3重の安全装置（HITL・スナップショットロールバック）、段階的導入ロードマップ</td></tr><tr><td style="text-align:left;"><strong>2. 社内閉域網での AI 導入・トークンコスト削減・API セキュリティ</strong></td><td style="text-align:left;"><code>SyncLLM_Proposal.pdf</code><br>+ <code>SyncAPIM_Proposal.pdf</code><br>+ <code>SyncWatch_Proposal.pdf</code><br>+ <code>SyncVerse_Proposal.pdf</code></td><td style="text-align:left;">社内ローカル LLM（vLLM/Ollama）連携、トークンコスト50%削減、個人情報の二重マスキング、Shadow API の発見および1分以内の誤検知ゼロ仮想パッチ</td></tr><tr><td style="text-align:left;"><strong>3. 新規システム・バックオフィス・Eコマース構築および SI 事業管理</strong></td><td style="text-align:left;"><code>SyncBoot_Proposal.pdf</code><br>+ <code>SyncCMS_Proposal.pdf</code><br>+ <code>SyncShop_Proposal.pdf</code><br>+ <code>SyncOps_Proposal.pdf</code></td><td style="text-align:left;">構築期間を半減する標準バックオフィス、SEO/GEO コンテンツ自動化、逆ザヤ防止の8モジュール MSA コマース、韓国型 SI リアルタイム損益・下請管理</td></tr><tr><td style="text-align:left;"><strong>4. 現場データのセルフ分析・Web データ収集・QA 自動化</strong></td><td style="text-align:left;"><code>SyncInsight_Proposal.pdf</code><br>+ <code>SyncCrawl_Proposal.pdf</code><br>+ <code>SyncETA_Proposal.pdf</code><br>+ <code>SyncSDK_Proposal.pdf</code></td><td style="text-align:left;">SQL 不要の3秒セキュア DB 照会、サイト改修でも止まらない自己修復型 Web 収集・テスト自動化、15大コーディングエンジンおよび4大成果物自動化</td></tr></tbody></table><hr><h2 id="_5-統合ライブデモおよびデスクトップアプリ体験のご案内" tabindex="-1">5. 統合ライブデモおよびデスクトップアプリ体験のご案内 <a class="header-anchor" href="#_5-統合ライブデモおよびデスクトップアプリ体験のご案内" aria-label="Permalink to “5. 統合ライブデモおよびデスクトップアプリ体験のご案内”">​</a></h2><ul><li><strong>統合ライブデモポータル</strong>：<a href="https://sync.empasy.io/ja/" target="_blank" rel="noreferrer">https://sync.empasy.io/ja/</a> にて、12大製品すべての実際の管理者・ユーザー稼働画面を今すぐご体験いただけます。</li><li><strong>SyncETA デスクトップアプリダウンロード</strong>：<a href="https://empasy.io/ja/download_eta.html" target="_blank" rel="noreferrer">https://empasy.io/ja/download_eta.html</a> から Windows / macOS 用のインストーラーをダウンロードし、お使いの PC ですぐにクリック録画と自動テストを実行いただけます。</li></ul>',20)])])}const S=e(a,[["render",l]]);export{y as __pageData,S as default};
